# Writes obj\...\EmbeddedApiKey.g.cs with the Claude API key masked, for "dotnet publish" on
# Diego's PC only (see Services/Ai/EmbeddedApiKey.cs). The key comes from a DPAPI-protected file
# outside the repository, readable only by Diego's Windows user. Nothing here holds the key, and
# the generated file lives under obj\, which git ignores. Never prints the key.
param(
    [Parameter(Mandatory)] [string] $KeyFile,
    [Parameter(Mandatory)] [string] $OutFile
)
$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.Security

$plain = [Security.Cryptography.ProtectedData]::Unprotect(
    [IO.File]::ReadAllBytes($KeyFile),
    [Text.Encoding]::UTF8.GetBytes('Zentra.BuildKey.v1'),
    'CurrentUser')
try {
    $mask = New-Object byte[] $plain.Length
    [Security.Cryptography.RandomNumberGenerator]::Fill($mask)
    $masked = New-Object byte[] $plain.Length
    for ($i = 0; $i -lt $plain.Length; $i++) { $masked[$i] = $plain[$i] -bxor $mask[$i] }

    $code = @"
// <auto-generated>Written by tools/embed-api-key.ps1 when publishing. Never commit.</auto-generated>
namespace optimizerDuck.Services.Ai;

internal static partial class EmbeddedApiKey
{
    static partial void Load(ref byte[]? masked, ref byte[]? mask)
    {
        masked = [$($masked -join ', ')];
        mask = [$($mask -join ', ')];
    }
}
"@
    New-Item -ItemType Directory -Force (Split-Path $OutFile) | Out-Null
    [IO.File]::WriteAllText($OutFile, $code, (New-Object Text.UTF8Encoding $false))
    Write-Host "Zentra: clave de la API incluida en esta publicación ($($plain.Length) bytes)."
}
finally {
    [Array]::Clear($plain, 0, $plain.Length)
}
